/* Проекты ↔ трекеры задач: Jira, YouTrack, Яндекс Трекер, Kaiten, Redmine. Задачи плана (спринт, выделенные или все)
   уходят в трекер: новые заводятся, уже связанные — обновляются (название, срок, оценка). Обратно: статус и часы —
   в «готово» и «статус» плана, одной операцией отмены. Отклонения: просрочка, перерасход часов, расхождение статусов.
   Связи «задача плана → задача трекера» лежат в проекте (скрытое поле панели), ключ доступа — в хранилище браузера. */
const ЗЕЛЁНЫЙ = '#2b8a3e', КРАСНЫЙ = '#c92a2a', СЕРЫЙ = '#868e96', ЖЁЛТЫЙ = '#e67700';
const АДРЕСА = {'Jira': 'https://jira.example.ru', 'YouTrack': 'https://youtrack.example.ru', 'Яндекс Трекер': 'https://api.tracker.yandex.net', 'Kaiten': 'https://компания.kaiten.ru', 'Redmine': 'https://redmine.example.ru'};
const ПРОЕКТ_ПОДСКАЗКА = {'Jira': 'ключ проекта: PRJ', 'YouTrack': 'краткое имя проекта: PRJ', 'Яндекс Трекер': 'ключ очереди: TEST', 'Kaiten': 'номер доски: 12345', 'Redmine': 'идентификатор проекта: my-project'};
async function безСбоя(f){ try { return await f(); } catch(e){ панель.сообщение(e.message); панель.поле('итог', [{текст: e.message, цвет: КРАСНЫЙ}]); } }
const часы = сек => сек == null ? null : Math.round(сек / 36) / 100;
/* ISO-длительность «P1DT2H30M» (Трекер) → часы; рабочий день — 8 часов */
function изISO(s){ const м = String(s || '').match(/^P(?:(\d+)W)?(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$/); if(!м) return null; return (+м[1] || 0) * 40 + (+м[2] || 0) * 8 + (+м[3] || 0) + (+м[4] || 0) / 60 + (+м[5] || 0) / 3600; }
const вISO = ч => 'PT' + Math.round(ч * 60) + 'M';

/* ---------- доступ ---------- */
function настройки(){
  const п = параметры({});
  const тип = п.тип || 'Jira';
  const ключ = String(п.ключ || '').trim() || хранилище.взять('ключ:' + тип, '');
  let адрес = String(п.адрес || '').trim().replace(/\/+$/, '');
  if(тип === 'Яндекс Трекер' && !адрес) адрес = АДРЕСА[тип];
  if(!/^https?:\/\//.test(адрес)) throw new Error('Впишите адрес трекера (https://…)');
  if(!ключ) throw new Error('Впишите ключ доступа (токен) — он хранится только в этом браузере');
  if(/[^\x21-\x7e]/.test(ключ)) throw new Error('В ключе доступа есть недопустимые знаки (русские буквы или пробелы) — скопируйте токен из трекера ещё раз');
  if(!String(п.проект || '').trim()) throw new Error('Впишите ' + ПРОЕКТ_ПОДСКАЗКА[тип]);
  return Object.assign({}, п, {тип, ключ, адрес, проект: String(п.проект).trim()});
}
const base64 = s => btoa(unescape(encodeURIComponent(s)));
async function вызов(н, метод, путь, тело, заголовки){
  const о = await запрос(н.адрес + путь, {метод, заголовки: Object.assign({'Content-Type': 'application/json', Accept: 'application/json'}, ТРЕКЕРЫ[н.тип].доступ(н), заголовки || {}), тело: тело === undefined ? undefined : JSON.stringify(тело), срок: 30000});
  if(!о.ок){
    const подробно = о.тело ? (о.тело.errorMessages || о.тело.errors || о.тело.error_description || о.тело.error || о.тело.errorMessage || о.тело.message) : '';
    throw new Error(н.тип + ': ' + метод + ' ' + путь + ' — ' + (о.код === 401 || о.код === 403 ? 'нет доступа (проверьте ключ' + (н.тип === 'Яндекс Трекер' ? ' и номер организации' : '') + ')' : о.код === 404 ? 'не найдено' : 'ответ ' + о.код) + (подробно ? ': ' + (typeof подробно === 'string' ? подробно : JSON.stringify(подробно)).slice(0, 200) : ''));
  }
  return о.тело;
}
/* статус трекера → вид: 'новая' | 'в работе' | 'готово' */
const видПоИмени = s => /closed|resolved|done|fixed|verified|закрыт|решен|решён|готов|выполн|сделан/i.test(s || '') ? 'готово' : /progress|review|test|работ|провер|ревью|тест/i.test(s || '') ? 'в работе' : 'новая';

const ТРЕКЕРЫ = {
  'Jira': {
    доступ: н => ({Authorization: н.логин ? 'Basic ' + base64(н.логин + ':' + н.ключ) : 'Bearer ' + н.ключ}),
    ссылка: (н, к) => н.адрес + '/browse/' + к,
    async проверить(н){ const п = await вызов(н, 'GET', '/rest/api/2/project/' + encodeURIComponent(н.проект)); return 'проект «' + (п.name || н.проект) + '»'; },
    async создать(н, з){ const поля = {project: {key: н.проект}, summary: з.имя, description: з.описание, issuetype: {name: н.видЗадачи || 'Task'}};
      if(з.срок) поля.duedate = з.срок; if(з.оценка) поля.timetracking = {originalEstimate: Math.round(з.оценка * 60) + 'm'};
      return (await вызов(н, 'POST', '/rest/api/2/issue', {fields: поля})).key; },
    async обновить(н, к, з){ const поля = {summary: з.имя}; if(з.срок) поля.duedate = з.срок; if(з.оценка) поля.timetracking = {originalEstimate: Math.round(з.оценка * 60) + 'm'};
      await вызов(н, 'PUT', '/rest/api/2/issue/' + encodeURIComponent(к), {fields: поля}); },
    async прочитать(н, к){ const и = (await вызов(н, 'GET', '/rest/api/2/issue/' + encodeURIComponent(к) + '?fields=summary,status,timespent,timeoriginalestimate,duedate,assignee')).fields;
      const кат = и.status && и.status.statusCategory && и.status.statusCategory.key;
      return {заголовок: и.summary, статус: (и.status || {}).name || '', вид: кат === 'done' ? 'готово' : кат === 'indeterminate' ? 'в работе' : кат === 'new' ? 'новая' : видПоИмени((и.status || {}).name),
        потрачено: часы(и.timespent), оценка: часы(и.timeoriginalestimate), срок: и.duedate || null, кто: и.assignee ? и.assignee.displayName : ''}; },
  },
  'YouTrack': {
    доступ: н => ({Authorization: 'Bearer ' + н.ключ}),
    ссылка: (н, к) => н.адрес + '/issue/' + к,
    async idПроекта(н){ if(н._id) return н._id; const сп = await вызов(н, 'GET', '/api/admin/projects?fields=id,shortName,name&$top=500'); const п = (сп || []).find(x => x.shortName === н.проект || x.name === н.проект);
      if(!п) throw new Error('YouTrack: проекта «' + н.проект + '» нет'); н._id = п.id; return п.id; },
    async проверить(н){ await this.idПроекта(н); return 'проект «' + н.проект + '»'; },
    async создать(н, з){ return (await вызов(н, 'POST', '/api/issues?fields=idReadable', {project: {id: await this.idПроекта(н)}, summary: з.имя, description: з.описание})).idReadable; },
    async обновить(н, к, з){ await вызов(н, 'POST', '/api/issues/' + encodeURIComponent(к) + '?fields=idReadable', {summary: з.имя}); },
    async прочитать(н, к){ const и = await вызов(н, 'GET', '/api/issues/' + encodeURIComponent(к) + '?fields=idReadable,summary,resolved,customFields(name,value(name,minutes,presentation))');
      const поле = имя => (и.customFields || []).find(f => new RegExp(имя, 'i').test(f.name)), знач = f => f && f.value;
      const сост = знач(поле('^(State|Состояние)$')), потр = знач(поле('^(Spent time|Затраченное время)$')), оц = знач(поле('^(Estimation|Оценка)$')), кто = знач(поле('^(Assignee|Исполнитель)$'));
      return {заголовок: и.summary, статус: сост ? сост.name : '', вид: и.resolved ? 'готово' : видПоИмени(сост && сост.name), потрачено: потр && потр.minutes != null ? потр.minutes / 60 : null,
        оценка: оц && оц.minutes != null ? оц.minutes / 60 : null, срок: null, кто: кто ? кто.name || '' : ''}; },
  },
  'Яндекс Трекер': {
    доступ: н => Object.assign({Authorization: (/^t1\./.test(н.ключ) ? 'Bearer ' : 'OAuth ') + н.ключ}, н.видОрг === 'Yandex Cloud' ? {'X-Cloud-Org-ID': н.организация} : {'X-Org-ID': н.организация}),
    ссылка: (н, к) => 'https://tracker.yandex.ru/' + к,
    async проверить(н){ if(!String(н.организация || '').trim()) throw new Error('Впишите номер организации'); const о = await вызов(н, 'GET', '/v2/queues/' + encodeURIComponent(н.проект)); return 'очередь «' + (о.name || н.проект) + '»'; },
    async создать(н, з){ const т = {queue: н.проект, summary: з.имя, description: з.описание}; if(з.срок) т.deadline = з.срок; if(з.оценка) т.originalEstimation = вISO(з.оценка);
      return (await вызов(н, 'POST', '/v2/issues/', т)).key; },
    async обновить(н, к, з){ const т = {summary: з.имя}; if(з.срок) т.deadline = з.срок; if(з.оценка) т.originalEstimation = вISO(з.оценка); await вызов(н, 'PATCH', '/v2/issues/' + encodeURIComponent(к), т); },
    async прочитать(н, к){ const и = await вызов(н, 'GET', '/v2/issues/' + encodeURIComponent(к));
      const ст = и.status || {}, тип = (и.statusType || {}).key || '';
      return {заголовок: и.summary, статус: ст.display || ст.key || '', вид: /done|resolved|closed/.test(тип) || /^(closed|resolved|done)$/.test(ст.key || '') ? 'готово' : /inProgress|in_progress|paused/i.test(тип) || /progress|review|testing/i.test(ст.key || '') ? 'в работе' : видПоИмени(ст.display),
        потрачено: изISO(и.spent), оценка: изISO(и.originalEstimation || и.estimation), срок: и.deadline || null, кто: и.assignee ? и.assignee.display || '' : ''}; },
  },
  'Kaiten': {
    доступ: н => ({Authorization: 'Bearer ' + н.ключ}),
    ссылка: (н, к) => н.адрес + '/' + к,
    async проверить(н){ const д = await вызов(н, 'GET', '/api/latest/boards/' + encodeURIComponent(н.проект)); return 'доска «' + (д.title || н.проект) + '»'; },
    async создать(н, з){ const т = {title: з.имя, board_id: +н.проект, description: з.описание}; if(+н.колонка) т.column_id = +н.колонка; if(з.срок) т.due_date = з.срок; if(з.оценка) т.size_text = з.оценка + ' ч';
      return String((await вызов(н, 'POST', '/api/latest/cards', т)).id); },
    async обновить(н, к, з){ const т = {title: з.имя}; if(з.срок) т.due_date = з.срок; await вызов(н, 'PATCH', '/api/latest/cards/' + encodeURIComponent(к), т); },
    async прочитать(н, к){ const и = await вызов(н, 'GET', '/api/latest/cards/' + encodeURIComponent(к));
      let потрачено = null; try { const л = await вызов(н, 'GET', '/api/latest/cards/' + encodeURIComponent(к) + '/time-logs'); if(Array.isArray(л)) потрачено = л.reduce((a, x) => a + (+x.time_spent || 0), 0) / 60; } catch(e){}
      return {заголовок: и.title, статус: и.state === 3 ? 'готово' : и.state === 2 ? 'в работе' : 'в очереди', вид: и.state === 3 ? 'готово' : и.state === 2 ? 'в работе' : 'новая',
        потрачено, оценка: parseFloat(String(и.size_text || '').replace(',', '.')) || null, срок: и.due_date ? String(и.due_date).slice(0, 10) : null, кто: (и.members || []).map(m => m.full_name).filter(Boolean).join(', ')}; },
  },
  'Redmine': {
    доступ: н => ({'X-Redmine-API-Key': н.ключ}),
    ссылка: (н, к) => н.адрес + '/issues/' + к,
    async проверить(н){ const о = await вызов(н, 'GET', '/projects/' + encodeURIComponent(н.проект) + '.json'); return 'проект «' + ((о.project || {}).name || н.проект) + '»'; },
    async создать(н, з){ const т = {project_id: н.проект, subject: з.имя, description: з.описание}; if(з.начало) т.start_date = з.начало; if(з.срок) т.due_date = з.срок; if(з.оценка) т.estimated_hours = з.оценка;
      return String((await вызов(н, 'POST', '/issues.json', {issue: т})).issue.id); },
    async обновить(н, к, з){ const т = {subject: з.имя}; if(з.срок) т.due_date = з.срок; if(з.оценка) т.estimated_hours = з.оценка; await вызов(н, 'PUT', '/issues/' + encodeURIComponent(к) + '.json', {issue: т}); },
    async прочитать(н, к){ const и = (await вызов(н, 'GET', '/issues/' + encodeURIComponent(к) + '.json')).issue;
      const ст = и.status || {};
      return {заголовок: и.subject, статус: ст.name || '', вид: ст.is_closed || видПоИмени(ст.name) === 'готово' ? 'готово' : (и.done_ratio > 0 || видПоИмени(ст.name) === 'в работе') ? 'в работе' : 'новая',
        потрачено: и.spent_hours != null ? и.spent_hours : null, оценка: и.estimated_hours != null ? и.estimated_hours : null, срок: и.due_date || null, процент: и.done_ratio, кто: и.assigned_to ? и.assigned_to.name : ''}; },
  },
};

/* ---------- связи «задача плана → задача трекера» — в проекте ---------- */
/* {тип трекера: {id задачи плана: ключ в трекере}} — у каждого трекера свои */
function всеСвязи(){ try { return JSON.parse(параметры({}).связи || '{}') || {}; } catch(e){ return {}; } }
function связи(тип){ return Object.assign({}, всеСвязи()[тип || параметры({}).тип || 'Jira'] || {}); }
function запомнитьСвязи(с, тип){ const все = всеСвязи(); все[тип || параметры({}).тип || 'Jira'] = с; панель.поле('связи', JSON.stringify(все)); }

function какиеЗадачи(п){
  const все = проект.задачи.filter(t => !t.сводная);
  if(п.что === 'Выделенные задачи'){ const в = new Set((проект.выделение || {}).выбрано || []); const сп = все.filter(t => в.has(t.id)); if(!сп.length) throw new Error('Выделите задачи в плане'); return сп; }
  if(п.что === 'Задачи спринта'){ const с = String(п.спринт || '').trim(); if(!с) throw new Error('Впишите спринт'); const сп = все.filter(t => String(t.спринт) === с); if(!сп.length) throw new Error('В спринте «' + с + '» нет задач'); return сп; }
  return все;
}
function описаниеЗадачи(t){
  return 'Задача плана «' + (проект.имя || 'Проект') + '», № ' + t['№'] + '.\nСроки по плану: ' + t.начало + ' — ' + t.окончание + (t.трудоёмкость ? ', трудоёмкость ' + t.трудоёмкость + ' ч' : '') + '.'
    + (t.исполнители && t.исполнители.length ? '\nИсполнители: ' + t.исполнители.join(', ') + '.' : '') + (t.описание ? '\n\n' + t.описание : '');
}

/* ---------- кнопки ---------- */
function Старт(){ const п = параметры({}); if(!п.адрес) панель.поле('адрес', АДРЕСА[п.тип || 'Jira']); показатьСвязи(); }
function ТипСменился(){ const п = параметры({}); прочитано = {}; ряды = []; панель.поле('адрес', хранилище.взять('адрес:' + п.тип, АДРЕСА[п.тип] || '')); панель.поле('проПроект', [{текст: 'Проект в трекере — ' + (ПРОЕКТ_ПОДСКАЗКА[п.тип] || ''), цвет: СЕРЫЙ}]); }
function показатьСвязи(){ const с = связи(), n = Object.keys(с).length; панель.поле('итог', n ? [{текст: 'Связано задач с трекером ' + (параметры({}).тип || 'Jira') + ': ' + n, жирный: true}] : [{текст: 'Задачи плана ещё не связаны с трекером', цвет: СЕРЫЙ}]); }
async function Проверить(){ return безСбоя(async () => {
  const н = настройки();
  const что = await ТРЕКЕРЫ[н.тип].проверить(н);
  хранилище.тайно('ключ:' + н.тип, н.ключ); хранилище.положить('адрес:' + н.тип, н.адрес);
  панель.поле('доступ', [{текст: '✓ ' + н.тип + ': ' + что + ' — доступ есть', цвет: ЗЕЛЁНЫЙ}]);
  панель.сообщение('Связь с трекером есть; ключ запомнен в этом браузере');
}); }
async function Отправить(){ return безСбоя(async () => {
  const н = настройки(), т = ТРЕКЕРЫ[н.тип], с = связи();
  const задачи = какиеЗадачи(н);
  let новых = 0, обновлено = 0; const сбои = [];
  for(const t of задачи){
    const з = {имя: t.имя || ('Задача ' + t['№']), описание: описаниеЗадачи(t), начало: t.начало, срок: н.сроки ? t.окончание : null, оценка: н.оценка && t.трудоёмкость ? t.трудоёмкость : null};
    try {
      if(с[t.id]){ if(н.главный === 'Названия — из плана'){ await т.обновить(н, с[t.id], з); обновлено++; } }
      else { с[t.id] = await т.создать(н, з); новых++; }
    } catch(e){ сбои.push(t['№'] + ' ' + t.имя + ': ' + e.message); if(сбои.length >= 3 && !новых && !обновлено) break; }
    if((новых + обновлено) % 10 === 0 && новых + обновлено) панель.сообщение('В трекер ушло ' + (новых + обновлено) + ' из ' + задачи.length + '…');
  }
  запомнитьСвязи(с, н.тип);
  хранилище.тайно('ключ:' + н.тип, н.ключ); хранилище.положить('адрес:' + н.тип, н.адрес);
  const части = [{текст: 'Заведено в трекере: ' + новых + (обновлено ? ', обновлено: ' + обновлено : '') + '. Связано всего: ' + Object.keys(с).length, жирный: true, цвет: сбои.length ? ЖЁЛТЫЙ : ЗЕЛЁНЫЙ}];
  for(const x of сбои.slice(0, 5)) части.push({текст: '\n✗ ' + x, цвет: КРАСНЫЙ});
  панель.поле('итог', части);
  панель.сообщение('В трекер: новых ' + новых + ', обновлено ' + обновлено + (сбои.length ? ', сбоев ' + сбои.length : ''));
}); }
/* статус трекера → статус и «готово» плана */
function вПлан(и, t){
  if(и.вид === 'готово') return {готово: 100, статус: 'выполнено'};
  if(и.вид === 'новая') return {готово: 0, статус: 'не начато'};
  let г = и.процент != null && и.процент > 0 ? и.процент : null;
  const оценка = и.оценка || t.трудоёмкость;
  if(г === null && и.потрачено != null && оценка) г = Math.round(и.потрачено / оценка * 100);
  return {готово: Math.max(1, Math.min(95, г == null ? 10 : г)), статус: 'в работе'};
}
let прочитано = {};      /* ключ трекера → прочитанное: для отчёта отклонений */
async function Забрать(){ return безСбоя(async () => {
  const н = настройки(), т = ТРЕКЕРЫ[н.тип], с = связи();
  const ids = Object.keys(с).filter(id => проект.задача(id));
  if(!ids.length) throw new Error('Связанных задач нет — сначала «Отправить в трекер»');
  let правок = 0, имён = 0; const сбои = [];
  for(const id of ids){
    let и;
    try { и = await т.прочитать(н, с[id]); } catch(e){ сбои.push(с[id] + ': ' + e.message); continue; }
    прочитано[с[id]] = и;
    const t = проект.задача(id), нов = вПлан(и, t), правка = {};
    if(Math.abs((t.готово || 0) - нов.готово) >= 1) правка.готово = нов.готово;
    if(t.статус !== нов.статус && !(нов.статус === 'выполнено' && t.статус === 'принято')) правка.статус = нов.статус;
    if(н.главный === 'Названия — из трекера' && и.заголовок && и.заголовок !== t.имя){ правка.имя = и.заголовок; имён++; }
    if(Object.keys(правка).length){ проект.правитьЗадачу(id, правка); правок++; }
  }
  const части = [{текст: 'Прочитано задач: ' + (ids.length - сбои.length) + ', правок в плане: ' + правок + (имён ? ' (названий: ' + имён + ')' : ''), жирный: true, цвет: сбои.length ? ЖЁЛТЫЙ : ЗЕЛЁНЫЙ}];
  for(const x of сбои.slice(0, 5)) части.push({текст: '\n✗ ' + x, цвет: КРАСНЫЙ});
  панель.поле('итог', части);
  панель.сообщение('Из трекера: правок ' + правок + ' — «Отменить» вернёт их разом');
  отклонения(н, с);
}); }
/* ---------- отклонения ---------- */
let ряды = [];
function отклонения(н, с){
  const сегодня = new Date().toISOString().slice(0, 10);
  ряды = [];
  for(const [id, к] of Object.entries(с)){
    const t = проект.задача(id), и = прочитано[к]; if(!t || !и) continue;
    const беды = [];
    if(и.вид !== 'готово' && t.окончание && t.окончание < сегодня) беды.push('просрочена: по плану до ' + t.окончание);
    if(и.срок && t.окончание && и.срок > t.окончание) беды.push('срок в трекере ' + и.срок + ' позже плана ' + t.окончание);
    const оценка = и.оценка || t.трудоёмкость;
    if(и.потрачено != null && оценка && и.потрачено > оценка * 1.1) беды.push('часов ' + окр(и.потрачено) + ' при оценке ' + окр(оценка) + ' (+' + Math.round((и.потрачено / оценка - 1) * 100) + '%)');
    if(и.вид === 'новая' && t.начало && t.начало < сегодня) беды.push('по плану уже начата, в трекере — не начата');
    ряды.push({номер: t['№'], имя: t.имя, ключ: к, ссылка: ТРЕКЕРЫ[н.тип].ссылка(н, к), статус: и.статус, план: t.начало + ' — ' + t.окончание, срок: и.срок || '', оценка: оценка, потрачено: и.потрачено, кто: и.кто, беды});
  }
  const плохо = ряды.filter(р => р.беды.length);
  панель.поле('отчёт', плохо.length ? [{текст: 'С отклонениями: ' + плохо.length + ' из ' + ряды.length, жирный: true, цвет: КРАСНЫЙ}].concat(плохо.slice(0, 30).map(р => ({текст: '\n' + р.номер + ' ' + р.имя + ' (' + р.ключ + '): ' + р.беды.join('; ')})))
    : [{текст: ряды.length ? 'Отклонений нет: ' + ряды.length + ' задач идут по плану' : 'Сначала «Забрать статусы и часы»', жирный: true, цвет: ряды.length ? ЗЕЛЁНЫЙ : СЕРЫЙ}]);
  панель.список('отклонения', плохо.map(р => р.номер + ' · ' + р.ключ + ' · ' + р.беды.join('; ')));
}
const окр = x => Math.round(x * 10) / 10;
async function Отклонения(){ return безСбоя(async () => { if(!Object.keys(прочитано).length) return Забрать(); отклонения(настройки(), связи()); }); }
function КЗадаче(){ const п = параметры({}); const н = String(п.отклонения || '').split(' · ')[0]; if(н) проект.перейти(н); }
async function ОтчётCSV(){ return безСбоя(async () => {
  if(!ряды.length) throw new Error('Сначала «Забрать статусы и часы»');
  const кав = v => '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"';
  const строки = [['№', 'Задача', 'Ключ в трекере', 'Ссылка', 'Статус в трекере', 'Сроки по плану', 'Срок в трекере', 'Оценка, ч', 'Потрачено, ч', 'Исполнитель', 'Отклонения'].map(кав).join(';')]
    .concat(ряды.map(р => [р.номер, р.имя, р.ключ, р.ссылка, р.статус, р.план, р.срок, р.оценка == null ? '' : String(окр(р.оценка)).replace('.', ','), р.потрачено == null ? '' : String(окр(р.потрачено)).replace('.', ','), р.кто, р.беды.join('; ')].map(кав).join(';')));
  const о = await файл.выгрузить('Отклонения ' + (проект.имя || 'проекта') + '.csv', строки.join('\r\n'), {кодировка: 'windows-1251'});
  панель.сообщение(о && о.сохранено === false ? 'Сохранение отменено' : 'Отчёт сохранён');
}); }
